  function addItem(id,qty=1,quality=1,artifact=null){if(!itemDefs[id])return false;if(isArtifact(id)){if(itemCount(id)>0)return false;const provenance=copy(artifact?.provenance)||artifactProvenance(id,quality,artifact?.maker||'Unknown',artifact?.source||'Found');const maxDurability=clamp(Number(artifact?.maxDurability??100),55,100);player.inventory[id]={qty:1,qualitySum:quality,durability:clamp(Number(artifact?.durability??maxDurability),0,maxDurability),maxDurability,provenance};log(`Picked up ${itemDefs[id].name} (${qualityLabel(quality)}; ${provenance.maker}).`,'world');return true;}const slot=player.inventory[id]||(player.inventory[id]={qty:0,qualitySum:0,durability:null});slot.qty+=qty;slot.qualitySum+=quality*qty;log(`Picked up ${qty} ${itemDefs[id].name}${quality>1.05?` (${qualityLabel(quality)})`:''}.`,'world');return true;}
