  function log(text,type='world'){world.events.push({id:world.serial++,text,type,day:world.day,minute:world.minute});if(world.events.length>70)world.events.shift();renderLog();}
  let toastTimer=0;function toast(text){UI.toast.textContent=text;UI.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>UI.toast.classList.remove('show'),1500);}

  function zoneAt(x,y){return zones.find(z=>x>=z.x&&x<=z.x+z.w&&y>=z.y&&y<=z.y+z.h)||null;}
  function spawnResource(type,x,y,quality=1){world.resources.push({id:`r${world.serial++}`,type,x,y,r:type==='iron'?12:9,quality,respawn:0,available:true});}
  function seedResources(){world.resources.length=0;
    for(let i=0;i<16;i++)spawnResource('briarleaf',rand(180,830),rand(760,1060),rand(.9,1.8));
    for(let i=0;i<10;i++)spawnResource('mooncap',rand(1220,1660),rand(780,1080),rand(1.1,2.4));
    for(let i=0;i<14;i++)spawnResource('iron',rand(140,540),rand(250,610),rand(.8,2.5));
    for(let i=0;i<14;i++)spawnResource('wood',rand(1210,1680),rand(270,640),rand(.8,2.2));
  }
  function spawnWolf(x,y){world.enemies.push({id:`w${world.serial++}`,type:'wolf',x,y,r:12,hp:36,maxHp:36,attackCd:0,wander:rand(0,10),dead:false});}
  function spawnEmberback(x=335,y=430){world.enemies.push({id:'emberback',type:'emberback',name:'Emberback',x,y,r:20,hp:120,maxHp:120,attackCd:0,windup:0,wander:0,vx:0,vy:0,dead:false});return world.enemies.at(-1);}
  function seedEnemies(){world.enemies.length=0;for(let i=0;i<6;i++)spawnWolf(rand(1240,1670),rand(300,650));for(let i=0;i<3;i++)spawnWolf(rand(350,800),rand(820,1040));spawnEmberback();}

  function reset(){world.minute=8*60;world.day=1;world.weather='clear';world.weatherTimer=220;world.events=[];world.serial=1;player.x=900;player.y=600;player.hp=100;player.energy=100;player.coins=24;player.servicesCompleted=0;player.deeds={emberback:0};player.apprentice=freshApprentice();clearNavigation();player.inventory={};player.equippedTool=null;player.equippedWeapon=null;player.knownFor='nothing yet';player.standing='Unknown';for(const k of Object.keys(player.skills))player.skills[k]={xp:0,level:1};npcs=npcTemplates.map(newNPC);seedResources();seedEnemies();addItem('bread',2,1);log('A new day begins in Briar Glen. Everyone here has needs of their own.','world');save();}

  function memory(n,text){n.memory.push({day:world.day,text});if(n.memory.length>12)n.memory.shift();}
  function npcNeedScore(n,id){const raw=n.stock[id]||0,stock=isArtifact(id)&&raw>0&&!npcArtifactReady(n,id)?0:raw,bias=n.needBias[id]||0,target=isArtifact(id)?1:3;return bias*Math.max(0,target-stock)+(id==='bread'?n.hunger/35:0);}
  function topNeed(n){let best={id:'bread',score:0};for(const id of Object.keys(n.needBias)){const score=npcNeedScore(n,id);if(score>best.score)best={id,score};}return best;}
  function npcNeedText(n){const need=topNeed(n);return need.score>.6?`${itemDefs[need.id].name} matters most right now.`:'No urgent shortage.';}
  function requestFor(n){const need=topNeed(n);if(need.score<1.1)return null;const qty=isArtifact(need.id)?1:need.score>3?2:1;const reward=Math.round(itemDefs[need.id].base*qty*(1.35+need.score*.08));return{id:need.id,qty,reward,createdDay:world.day};}
  function pointSegmentDistance(p,a,b){const vx=b.x-a.x,vy=b.y-a.y,wx=p.x-a.x,wy=p.y-a.y,len=vx*vx+vy*vy;if(!len)return Math.hypot(wx,wy);const t=clamp((wx*vx+wy*vy)/len,0,1),px=a.x+t*vx,py=a.y+t*vy;return Math.hypot(p.x-px,p.y-py);}
  function dangerOnRoute(from,to,radius=95){let best=null,bd=radius;for(const e of world.enemies){if(e.dead)continue;const d=pointSegmentDistance(e,from,to);if(d<bd){best=e;bd=d;}}return best;}
  function fieldSpot(id,seeker=null,safeOnly=false){let nodes=world.resources.filter(r=>r.available&&r.type===id);if(safeOnly&&seeker)nodes=nodes.filter(r=>!dangerNear(r,125)&&!dangerOnRoute(seeker,r,95));if(nodes.length){nodes.sort((a,b)=>(seeker?dist(seeker,a):0)-(seeker?dist(seeker,b):0));return{x:nodes[0].x,y:nodes[0].y,id:nodes[0].id};}if(safeOnly)return null;return id==='iron'?{x:360,y:430}:id==='wood'?{x:1430,y:450}:id==='mooncap'?{x:1370,y:930}:id==='briarleaf'?{x:520,y:900}:null;}
  function relationValue(a,b){return Number(a?.relations?.[b?.id]||0);}
  function cooperationScore(a,b){return(relationValue(a,b)+relationValue(b,a))/2;}
  function canCooperate(a,b){return relationValue(a,b)>-1&&relationValue(b,a)>-1;}
  function supplierFor(seeker,id){const preferred=id==='bread'?'rowan':id==='tonic'?'mira':id==='pick'||id==='blade'?'alden':null;const candidates=npcs.filter(o=>o!==seeker&&(o.stock?.[id]||0)>0&&(!isArtifact(id)||npcArtifactReady(o,id))&&!o.socialCommitment&&canCooperate(o,seeker));candidates.sort((a,b)=>(cooperationScore(b,seeker)-cooperationScore(a,seeker))||((b.id===preferred)-(a.id===preferred))||((b.stock[id]||0)-(a.stock[id]||0))||(npcStackQuality(b,id)-npcStackQuality(a,id))||(dist(seeker,a)-dist(seeker,b)));return candidates[0]||null;}
  function promiseReliability(n){n.reliability=n.reliability&&typeof n.reliability==='object'?n.reliability:{kept:0,broken:0};n.reliability.kept=Math.max(0,Number(n.reliability.kept||0));n.reliability.broken=Math.max(0,Number(n.reliability.broken||0));return n.reliability;}
  function breakSocialPromise(supplier,reason='could not deliver'){const commitment=supplier?.socialCommitment;if(!commitment)return false;const requester=npcs.find(x=>x.id===commitment.requesterId),id=commitment.itemId;promiseReliability(supplier).broken+=1;supplier.socialCommitment=null;supplier.think=0;if(requester){requester.brokeredNeed=null;requester.think=0;relation(requester,supplier,-.65);relation(supplier,requester,-.25);memory(requester,`${supplier.name} broke the ${itemDefs[id].name} promise you brokered.`);memory(supplier,`I broke my ${itemDefs[id].name} promise to ${requester.name}; that damaged trust.`);log(`${supplier.name} broke the ${itemDefs[id].name} promise to ${requester.name}: ${reason}.`,'npc');}return true;}
  function brokerNeed(requester){const need=topNeed(requester);if(need.score<1.1||requester.brokeredNeed)return null;const supplier=supplierFor(requester,need.id);if(!supplier)return null;const commitment={requesterId:requester.id,itemId:need.id,createdDay:world.day,createdMinute:world.minute,brokeredBy:'player'};supplier.socialCommitment=commitment;supplier.productionPlan=null;supplier.seekSource=null;supplier.goal='deliver';supplier.target={x:requester.x,y:requester.y};supplier.goalText=`Promised ${requester.name} ${itemDefs[need.id].name} because you connected us`;supplier.think=9;requester.brokeredNeed={supplierId:supplier.id,itemId:need.id,createdDay:world.day};requester.seekSource=null;requester.goal='await';requester.target={...requester.work};requester.goalText=`Waiting on ${supplier.name}'s promised ${itemDefs[need.id].name}`;requester.think=9;memory(requester,`You connected ${supplier.name} to my need for ${itemDefs[need.id].name}.`);memory(supplier,`You connected me to ${requester.name}'s need for ${itemDefs[need.id].name}.`);log(`You brokered a ${itemDefs[need.id].name} promise between ${supplier.name} and ${requester.name}.`,'npc');return{requesterId:requester.id,supplierId:supplier.id,supplierName:supplier.name,itemId:need.id};}
  function relation(a,b,delta){a.relations??={};a.relations[b.id]=clamp((a.relations[b.id]||0)+delta,-5,10);}
  function liveEnemy(id){return world.enemies.find(e=>e.id===id&&!e.dead)||null;}
  function dangerNear(point,radius=120){let best=null,bd=radius;for(const e of world.enemies){if(e.dead)continue;const d=Math.hypot(e.x-point.x,e.y-point.y);if(d<bd){best=e;bd=d;}}return best;}
  function activeDangerReport(){for(const reporter of npcs){const report=reporter.blockedByDanger;if(!report)continue;const enemy=liveEnemy(report.enemyId);if(enemy)return{reporter,enemy,report};reporter.blockedByDanger=null;}return null;}
