  function npcExchange(n,need){if(isArtifact(need.id)&&npcArtifactReady(n,need.id)){n.seekSource=null;n.productionPlan=null;n.think=0;return false;}const supplier=n.seekSource&&npcs.find(x=>x.id===n.seekSource);if(supplier&&!canCooperate(supplier,n)){memory(n,`${supplier.name} and I are on poor terms, so I looked elsewhere for ${itemDefs[need.id].name}.`);n.seekSource=null;n.think=0;return false;}if(!supplier||supplier===n||n.exchangeCooldown>0||supplier.exchangeCooldown>0||dist(n,supplier)>50||(supplier.stock[need.id]||0)<1)return false;if(isArtifact(need.id)){supplier.stock[need.id]--;n.stock[need.id]=1;if(supplier.stockMeta?.[need.id]){n.stockMeta??={};n.stockMeta[need.id]=copy(supplier.stockMeta[need.id]);if(supplier.stock[need.id]<=0)delete supplier.stockMeta[need.id];}}else{const quality=npcRemoveStack(supplier,need.id,1);if(quality==null)return false;npcAddStack(n,need.id,1,quality);}n.trades=(n.trades||0)+1;supplier.trades=(supplier.trades||0)+1;n.exchangeCooldown=supplier.exchangeCooldown=9;relation(n,supplier,.25);relation(supplier,n,.15);memory(n,`${supplier.name} supplied ${itemDefs[need.id].name} when it mattered.`);memory(supplier,`${n.name} came to me for ${itemDefs[need.id].name}.`);log(`${supplier.name} supplied ${n.name} with ${itemDefs[need.id].name}.`,'npc');n.request=requestFor(n);return true;}
