    if(n.role==='herbalist'&&npcAtWork(n)&&n.productionCooldown<=0&&(n.stock.briarleaf||0)>=2&&(n.stock.mooncap||0)>=1){const shears=npcArtifactState(n,'shears');if(shears?.durability>0){const materialQuality=(npcStackQuality(n,'briarleaf')*2+npcStackQuality(n,'mooncap'))/3;npcRemoveStack(n,'briarleaf',2);npcRemoveStack(n,'mooncap',1);npcAddStack(n,'tonic',1,materialQuality);n.productionCooldown=18;const wear=Math.max(2,Math.round(5-(shears.quality-1)*1.5));shears.durability=Math.max(0,shears.durability-wear);shears.provenance.history.push(`Used by Mira to prepare Field Tonic on Day ${world.day}.`);if(shears.provenance.history.length>8)shears.provenance.history.shift();memory(n,'Prepared a Field Tonic from gathered plants.');if(shears.durability<=0){n.needBias.shears=Math.max(n.needBias.shears||0,7);memory(n,'My Herbal Shears failed while preparing medicine.');}}else n.needBias.shears=Math.max(n.needBias.shears||0,7);}
