  function npcSafety(n){if(n.goal!=='patrol')return;const call=activeDangerReport();if(!call){n.think=0;return;}if(call.enemy.type==='emberback'){n.goal='guard';n.target={...n.work};n.goalText='Holding Briar Glen while Emberback controls the quarry';n.think=5;if(!n.memory.some(m=>m.text.includes('Emberback is beyond routine patrol')))memory(n,'Emberback is beyond routine patrol; the quarry stays blocked until someone brings it down.');return;}const blade=npcArtifactState(n,'blade');if(!blade||blade.durability<=0){n.needBias.blade=Math.max(n.needBias.blade||0,6);n.goal='gear';n.target={...n.work};n.goalText='Cannot answer danger without a usable Warden Blade';n.request=requestFor(n);n.think=0;return;}n.target={x:call.enemy.x,y:call.enemy.y};if(dist(n,call.enemy)>55)return;call.enemy.dead=true;const wear=Math.max(4,Math.round(12-(blade.quality-1)*3));blade.durability=Math.max(0,blade.durability-wear);blade.provenance.history.push(`Used by Tamsin to clear danger for ${call.reporter.name} on Day ${world.day}.`);if(blade.provenance.history.length>8)blade.provenance.history.shift();const maker=blade.provenance.maker==='You'?'the blade you forged':`${blade.provenance.maker}'s blade`;memory(n,`Cleared a wolf that was blocking ${call.reporter.name}'s work with ${maker}.`);memory(call.reporter,`Tamsin cleared the wolf that stopped my work.`);relation(call.reporter,n,.35);relation(n,call.reporter,.2);call.reporter.blockedByDanger=null;call.reporter.think=0;if(blade.durability<=0){n.needBias.blade=Math.max(n.needBias.blade||0,6);memory(n,'My Warden Blade broke while keeping the road open.');}log(`Tamsin drove off a wolf so ${call.reporter.name} could get back to work.`,'npc');n.think=0;}
  function socialDelivery(n){if(n.goal!=='deliver'||!n.socialCommitment)return false;const commitment=n.socialCommitment,requester=npcs.find(x=>x.id===commitment.requesterId),id=commitment.itemId;if(requester&&isArtifact(id)&&npcArtifactReady(requester,id)){requester.brokeredNeed=null;n.socialCommitment=null;n.think=0;return false;}if(!requester||(n.stock?.[id]||0)<1){breakSocialPromise(n,!requester?'the requester was unavailable':'the promised stock was gone');return false;}n.target={x:requester.x,y:requester.y};if(dist(n,requester)>50)return false;if(isArtifact(id)){n.stock[id]--;requester.stock[id]=1;if(n.stockMeta?.[id]){requester.stockMeta??={};requester.stockMeta[id]=copy(n.stockMeta[id]);if(n.stock[id]<=0)delete n.stockMeta[id];}}else{const quality=npcRemoveStack(n,id,1);if(quality==null){breakSocialPromise(n,'the promised stock was gone');return false;}npcAddStack(requester,id,1,quality);}n.trades=(n.trades||0)+1;requester.trades=(requester.trades||0)+1;promiseReliability(n).kept+=1;relation(requester,n,.45);relation(n,requester,.3);requester.trust=clamp(requester.trust+.35,0,10);n.trust=clamp(n.trust+.2,0,10);memory(requester,`${n.name} kept the ${itemDefs[id].name} promise you brokered.`);memory(n,`I kept my ${itemDefs[id].name} promise to ${requester.name} after you connected us.`);log(`${n.name} delivered ${itemDefs[id].name} to ${requester.name} because of your introduction.`,'npc');requester.brokeredNeed=null;n.socialCommitment=null;requester.request=requestFor(requester);n.request=requestFor(n);requester.think=0;n.think=0;return true;}

  function updateNPC(n,dt){n.relations??={};n.productionCooldown=Math.max(0,(n.productionCooldown||0)-dt);n.exchangeCooldown=Math.max(0,(n.exchangeCooldown||0)-dt);n.think=(n.think||0)-dt;n.hunger=clamp(n.hunger+dt*.45,0,100);n.energy=clamp(n.energy-dt*(n.goal==='sleep'?-2.5:.18),0,100);n.mood=clamp(n.mood+dt*((n.hunger<55?1:-1)*.08),0,100);if(n.think<=0){chooseNpcGoal(n);n.think=rand(3,7);}if(n.goal==='seek'&&n.seekSource){const supplier=npcs.find(x=>x.id===n.seekSource);if(supplier)n.target={x:supplier.x,y:supplier.y};}if(n.goal==='deliver'&&n.socialCommitment){const requester=npcs.find(x=>x.id===n.socialCommitment.requesterId);if(requester)n.target={x:requester.x,y:requester.y};}if(n.goal==='seekService'&&n.seekingServiceFor){const service=damagedArtifactForNpc(n);if(!service){n.seekingServiceFor=null;n.think=0;}else if(dist(n,player)>65){n.target={x:player.x,y:player.y};n.goalText=`Seeking you to service ${itemDefs[n.seekingServiceFor].name}`;}else{n.target={x:n.x,y:n.y};n.goalText=`Waiting for you to service ${itemDefs[n.seekingServiceFor].name}`;}}if(n.goal==='seekProvider'&&n.seekingProviderFor){const req=n.request||requestFor(n),call=n.providerCall,elapsed=call?Math.max(0,worldMinuteStamp()-Number(call.startStamp||worldMinuteStamp())):0;if(!req||req.id!==n.seekingProviderFor){n.seekingProviderFor=null;n.providerCall=null;n.think=0;}else if(elapsed>300){missProviderCall(n,'I waited and you never came through');}else if(dist(n,player)>65){n.target={x:player.x,y:player.y};n.goalText=`Seeking you for ${itemDefs[n.seekingProviderFor].name}`;}else{n.target={x:n.x,y:n.y};n.goalText=itemCount(req.id)>=req.qty?`Waiting for your ${itemDefs[n.seekingProviderFor].name}`:`Waiting while you source ${itemDefs[n.seekingProviderFor].name}`;}}if(n.goal==='refer'&&n.pendingReferral){const recipient=npcs.find(x=>x.id===n.pendingReferral.recipientId);if(recipient){n.target={x:recipient.x,y:recipient.y};n.goalText=n.pendingReferral.kind==='provider'?`Going to tell ${recipient.name} you supply ${itemDefs[n.pendingReferral.itemId]?.name||'needed goods'}`:`Going to tell ${recipient.name} about your Smithing`;}else{n.pendingReferral=null;n.think=0;}}if(n.goal==='patrol'){const call=activeDangerReport();if(call)n.target={x:call.enemy.x,y:call.enemy.y};else n.think=0;}const dx=n.target.x-n.x,dy=n.target.y-n.y,d=Math.hypot(dx,dy);if(d>4){const speed=n.goal==='sleep'?65:45;n.x+=dx/d*speed*dt;n.y+=dy/d*speed*dt;}deliverSmithReferral(n);deliverProviderReferral(n);socialDelivery(n);npcSafety(n);npcEconomy(n);}

  function priceFor(n,id,mode='buy'){const def=itemDefs[id],need=npcNeedScore(n,id),stock=n.stock[id]||0,trust=n.trust;let p=def.base*(1+need*.12)*(1+Math.max(0,2-stock)*.08);if(mode==='sell')p*=.62+Math.min(.18,trust*.01);else p*=1.2-Math.min(.18,trust*.01);return Math.max(1,Math.round(p));}
  function helpNPC(n){const r=n.request||requestFor(n);if(!r){toast(`${n.name} has no urgent request`);return false;}if(itemCount(r.id)<r.qty){toast(`Need ${r.qty} ${itemDefs[r.id].name}`);return false;}const q=avgQuality(r.id),artifact=isArtifact(r.id)?artifactSnapshot(r.id):null;removeItem(r.id,r.qty);if(artifact){n.stock[r.id]=1;n.stockMeta??={};n.stockMeta[r.id]=artifact;n.seekSource=null;n.productionPlan=null;n.routeOverride=null;n.goal='idle';n.target={...n.work};n.think=0;}else npcAddStack(n,r.id,r.qty,q);n.trust=clamp(n.trust+1+Math.max(0,q-1)*.4+(artifact?.provenance?.maker==='You'?.25:0),0,10);const providerPremium=providerReliabilityPremium(n,r.id,r.reward);player.coins+=r.reward+Math.round((q-1)*3)+providerPremium;n.lastPlayerHelp=world.day;recordProviderExperience(n,r.id,r.qty,q);const answeredProviderCall=completeProviderCall(n,r.id)!=null;n.seekingProviderFor=null;if(answeredProviderCall&&n.goal==='seekProvider'){n.goal='idle';n.goalText='Supply received';n.target={...n.work};n.think=0;}memory(n,artifact?.provenance?.maker==='You'?`You brought the ${qualityLabel(q)} ${itemDefs[r.id].name} you made on Day ${artifact.provenance.madeDay} when it was needed.`:`You brought ${r.qty} ${itemDefs[r.id].name} when it was needed.`);if(providerPremium>0){memory(n,`I paid ${providerPremium}c extra because you answered when I came looking for you.`);log(`${n.name} paid ${providerPremium}c extra for reliable repeat service.`,'npc');}skillXp('rapport',8);deriveIdentity();toast(providerPremium>0?`${n.name} remembers that help · +${providerPremium}c reliability premium`:`${n.name} remembers that help`);log(`${n.name}'s shortage eased because you brought ${itemDefs[r.id].name}.`,'npc');n.request=null;save();return true;}
  function sellToNPC(n){const need=topNeed(n);const id=need.id;if(itemCount(id)<1){toast(`You have no ${itemDefs[id].name}`);return false;}const price=priceFor(n,id,'sell'),q=avgQuality(id),artifact=isArtifact(id)?artifactSnapshot(id):null;removeItem(id,1);if(artifact){n.stock[id]=1;n.stockMeta??={};n.stockMeta[id]=artifact;}else npcAddStack(n,id,1,q);player.coins+=Math.round(price*q);n.trust=clamp(n.trust+.15+(artifact?.provenance?.maker==='You'?.15:0),0,10);memory(n,artifact?.provenance?.maker==='You'?`Bought the ${qualityLabel(q)} ${itemDefs[id].name} you made.`:`Bought ${itemDefs[id].name} from you.`);deriveIdentity();save();toast(`Sold ${itemDefs[id].name} for ${Math.round(price*q)}c`);return true;}
  function buyFromNPC(n){const entries=Object.entries(n.stock).filter(([id,q])=>q>0&&itemDefs[id]&&(!isArtifact(id)||itemCount(id)===0));if(!entries.length){toast(`${n.name} has nothing spare you can carry`);return false;}entries.sort((a,b)=>priceFor(n,a[0],'buy')-priceFor(n,b[0],'buy'));const [id]=entries[0],artifact=isArtifact(id)?n.stockMeta?.[id]:null,q=artifact?.quality||npcStackQuality(n,id);const price=Math.round(priceFor(n,id,'buy')*q);if(player.coins<price){toast(`Need ${price}c`);return false;}player.coins-=price;if(isArtifact(id)){n.stock[id]--;if(n.stock[id]<=0&&n.stockMeta)delete n.stockMeta[id];}else npcRemoveStack(n,id,1);addItem(id,1,q,artifact||{maker:n.name,source:`${n.name}'s stock`});save();toast(`Bought ${itemDefs[id].name} for ${price}c`);return true;}

  function townNeedState(){const out={food:0,medicine:0,metal:0,materials:0};for(const n of npcs){for(const id of Object.keys(n.needBias||{})){const score=npcNeedScore(n,id),kind=itemDefs[id]?.kind;if(kind==='food')out.food+=score;else if(kind==='medicine'||kind==='herb')out.medicine+=score;else if(kind==='ore'||kind==='tool'||kind==='weapon')out.metal+=score;else out.materials+=score;}}world.townNeeds=out;return out;}
  function dominantTownNeed(){const needs=townNeedState(),[key,value]=Object.entries(needs).sort((a,b)=>b[1]-a[1])[0];return{key,value,label:{food:'food',medicine:'medicine and herbs',metal:'metal and tools',materials:'field materials'}[key]};}
  function deriveIdentity(){const totalTrust=npcs.reduce((s,n)=>s+n.trust,0),helped=npcs.filter(n=>n.trust>=1).length,craft=player.skills.smithing.level+player.skills.herbcraft.level,field=player.skills.fieldcraft.level,guard=player.skills.guard.level,emberbackDeed=player.deeds?.emberback?1:0;player.standing=totalTrust>=16?'Mainstay':totalTrust>=9?'Trusted':totalTrust>=4?'Known':'Unknown';const scores=[['keeping people supplied',totalTrust+helped*2],['keeping the Glen’s gear working',(player.servicesCompleted||0)*3+player.skills.smithing.level*2],['making useful things',craft*2],['bringing back what the Glen needs',field*2],['keeping the roads safe',guard*2+emberbackDeed*8]];scores.sort((a,b)=>b[1]-a[1]);player.knownFor=scores[0][1]>4?scores[0][0]:'nothing yet';}

  function gather(node){if(!node.available)return false;const pick=player.inventory.pick,pickReady=player.equippedTool==='pick'&&pick?.durability>0,pickQuality=pickReady?avgQuality('pick'):1;let q=node.quality+(player.skills.fieldcraft.level-1)*.12+(world.weather==='rain'&&itemDefs[node.type].kind==='herb'?.18:0);let qty=1;if(node.type==='iron'){if(pickReady){qty+=player.skills.fieldcraft.level>=3?1:0;q+=(pickQuality-1)*.18;pick.durability=Math.max(0,pick.durability-Math.max(2,6-Math.floor(pickQuality)));}else q-=.35;}if(node.type==='wood'&&pickReady)q-=.2;addItem(node.type,qty,clamp(q,.7,3));node.available=false;node.respawn=rand(60,120);player.energy=Math.max(0,player.energy-(node.type==='iron'?(pickReady?8:12):4));skillXp('fieldcraft',node.type==='iron'?5:3);if(player.equippedTool==='pick'&&pick&&!pick.durability)toast('Iron Pick broke — Mend it before the next hard job');save();return true;}
  function craft(id){const r=recipes[id];if(!r)return false;if(player.skills[r.skill].level<r.level){toast(`${skillDefs[r.skill].name} ${r.level} required`);return false;}if(isArtifact(id)&&itemCount(id)>0){toast(`You already carry a ${itemDefs[id].name}; singular gear keeps its own history.`);return false;}if(!hasItems(r.input)){toast(`Missing materials for ${itemDefs[id].name}`);return false;}let total=0,count=0;for(const [mat,q] of Object.entries(r.input)){total+=avgQuality(mat)*q;count+=q;}const materialQuality=total/count;consume(r.input);const quality=clamp(materialQuality+(player.skills[r.skill].level-1)*.15,.8,3);const artifact=isArtifact(id)?{provenance:{maker:'You',madeDay:world.day,source:'Player-forged',materialQuality,skillLevel:player.skills[r.skill].level,repairs:0,history:[`Forged by You on Day ${world.day} from ${qualityLabel(materialQuality)} materials.`]}}:null;if(!addItem(id,1,quality,artifact))return false;skillXp(r.skill,10);if(id==='pick')player.equippedTool='pick';if(id==='blade')player.equippedWeapon='blade';deriveIdentity();save();toast(`Crafted ${qualityLabel(quality)} ${itemDefs[id].name}`);return true;}
  function drinkTonic(){if(itemCount('tonic')<1){toast('No Field Tonic');return false;}const quality=avgQuality('tonic'),base=35+player.skills.herbcraft.level*3,qualityDelta=Math.round(clamp(quality-1,-.5,2)*6),heal=Math.max(1,base+qualityDelta),before=player.hp;removeItem('tonic',1);player.hp=clamp(player.hp+heal,0,player.maxHp);const restored=player.hp-before;save();toast(`${qualityLabel(quality)} Field Tonic restored ${restored} health${restored<heal?' · fully recovered':''}`);return true;}

  function nearestNPC(range=70){let best=null,bd=range;for(const n of npcs){const d=dist(player,n);if(d<bd){best=n;bd=d;}}return best;}
  function nearestResource(range=44){let best=null,bd=range;for(const r of world.resources){if(!r.available)continue;const d=dist(player,r);if(d<bd){best=r;bd=d;}}return best;}
  function nearestDrop(range=38){let best=null,bd=range;for(const d of world.drops){const dd=dist(player,d);if(dd<bd){best=d;bd=dd;}}return best;}
  function clearNavigation(){navigation.active=false;navigation.target=null;}
  function navigationEntity(target){if(!target)return null;if(target.kind==='npc')return npcs.find(n=>n.id===target.id)||null;if(target.kind==='resource')return world.resources.find(r=>r.id===target.id&&r.available)||null;if(target.kind==='drop')return world.drops.find(d=>d.id===target.id)||null;return null;}
  function navigationStop(target){return target?.kind==='npc'?62:target?.kind==='resource'?38:target?.kind==='drop'?30:7;}
  function interactNavigationTarget(target){if(!target)return false;if(target.kind==='npc'){const n=npcs.find(x=>x.id===target.id);if(n&&dist(player,n)<=70){renderNearby(n,true);return true;}}if(target.kind==='resource'){const r=world.resources.find(x=>x.id===target.id&&x.available);if(r&&dist(player,r)<=44)return gather(r);}if(target.kind==='drop'){const d=world.drops.find(x=>x.id===target.id);if(d&&dist(player,d)<=38){addItem(d.item,1,d.quality);world.drops=world.drops.filter(x=>x!==d);save();return true;}}return false;}
  function targetAtWorld(x,y){let best=null,bd=34;for(const n of npcs){const d=Math.hypot(n.x-x,n.y-y);if(d<bd){best={kind:'npc',id:n.id};bd=d;}}for(const r of world.resources){if(!r.available)continue;const d=Math.hypot(r.x-x,r.y-y);if(d<Math.min(bd,28)){best={kind:'resource',id:r.id};bd=d;}}for(const drop of world.drops){const d=Math.hypot(drop.x-x,drop.y-y);if(d<Math.min(bd,28)){best={kind:'drop',id:drop.id};bd=d;}}return best;}
  function setNavigation(x,y,target=null){navigation.x=clamp(Number(x)||0,18,world.w-18);navigation.y=clamp(Number(y)||0,18,world.h-18);navigation.target=target;navigation.active=true;return{x:navigation.x,y:navigation.y,target:copy(target)};}
  function navigateToTarget(kind,id){const target={kind,id},entity=navigationEntity(target);if(!entity)return false;setNavigation(entity.x,entity.y,target);return true;}
  function interact(){clearNavigation();const n=nearestNPC();if(n){renderNearby(n,true);return true;}const r=nearestResource();if(r)return gather(r);const d=nearestDrop();if(d){addItem(d.item,1,d.quality);world.drops=world.drops.filter(x=>x!==d);save();return true;}toast('Nothing useful within reach');return false;}

  function combatProfile(){const blade=player.inventory.blade,bladeReady=player.equippedWeapon==='blade'&&blade?.durability>0,bladeQuality=bladeReady?avgQuality('blade'):1;return{bladeReady,bladeQuality,range:bladeReady?58:42,damage:bladeReady?Math.round((18+player.skills.guard.level*2)*(1+(bladeQuality-1)*.18)):9+player.skills.guard.level};}
  function releaseEmberbackBlockedWorkers(e){if(e?.type!=='emberback')return[];const released=[];for(const n of npcs){if(n.blockedByDanger?.enemyId!==e.id)continue;const report=n.blockedByDanger;n.blockedByDanger=null;n.trust=clamp(n.trust+.5,0,10);if(n.avoidEnemyId===e.id){n.avoidEnemyId=null;n.routeOverride=null;}memory(n,`Emberback fell; the Old Quarry is open again. I can return to ${itemDefs[report.itemId]?.name||'work'}.`);n.think=0;chooseNpcGoal(n);released.push(n.name);}if(released.length)log(`Emberback's fall reopened the Old Quarry. ${released.join(', ')} can return to work.`,'world');return released;}
  function defeatEnemy(e){if(!e||e.dead)return false;e.dead=true;if(e.type==='emberback'){player.deeds=player.deeds&&typeof player.deeds==='object'?player.deeds:{emberback:0};const firstDeed=!player.deeds.emberback;player.deeds.emberback=1;if(firstDeed){const tamsin=npcs.find(n=>n.id==='tamsin');if(tamsin){tamsin.trust=clamp(tamsin.trust+.75,0,10);memory(tamsin,'You brought down Emberback and reopened the Old Quarry for the Glen.');}}deriveIdentity();world.drops.push({id:`d${world.serial++}`,x:e.x-8,y:e.y,item:'hide',quality:2.8},{id:`d${world.serial++}`,x:e.x+8,y:e.y,item:'hide',quality:2.8});player.coins+=30;log('Emberback fell in the Old Quarry. Two fine hides and a 30c bounty mark the road safe enough to work again.','combat');releaseEmberbackBlockedWorkers(e);toast('Emberback defeated · 30c · fine hides');}else{world.drops.push({id:`d${world.serial++}`,x:e.x,y:e.y,item:'hide',quality:rand(1,2.2)});player.coins+=3;log('A wolf fell. Its hide may matter more to someone than the coins.','combat');}return true;}
  function attack(){if(player.attackCd>0||player.energy<4)return;player.attackCd=.38;player.attackArc=.14;player.energy-=4;const profile=combatProfile(),blade=player.inventory.blade;if(player.equippedWeapon==='blade'&&blade&&!profile.bladeReady)toast('The Warden Blade is broken — fighting without its edge');for(const e of world.enemies){if(e.dead)continue;if(dist(player,e)<=profile.range){e.hp-=profile.damage;skillXp('guard',2);if(profile.bladeReady)blade.durability=Math.max(0,blade.durability-1);if(e.hp<=0)defeatEnemy(e);break;}}}
  function updateEmberback(e,dt){if(e.dead)return;e.attackCd=Math.max(0,e.attackCd-dt);const d=dist(player,e);if(e.windup>0){const before=e.windup;e.windup=Math.max(0,e.windup-dt);if(before>0&&e.windup<=0&&d<68){let dmg=18;if(player.guarded){dmg=2;player.guarded=false;e.hp-=9+player.skills.guard.level*3;toast('Brace held — Emberback staggered');if(e.hp<=0)defeatEnemy(e);}player.hp=Math.max(0,player.hp-dmg);if(player.hp<=0){player.hp=player.maxHp;player.energy=50;player.x=900;player.y=600;player.coins=Math.max(0,player.coins-10);log('Emberback drove you from the quarry. You were carried back to Briar Glen.','combat');}}return;}if(d<300){const dx=player.x-e.x,dy=player.y-e.y,dd=Math.max(1,Math.hypot(dx,dy));if(dd>48){e.x+=dx/dd*54*dt;e.y+=dy/dd*54*dt;}else if(e.attackCd<=0){e.windup=.7;e.attackCd=1.9;toast('Emberback paws the earth — Brace!');}}else{e.wander-=dt;if(e.wander<=0){e.vx=rand(-1,1);e.vy=rand(-1,1);e.wander=rand(3,7);}e.x=clamp(e.x+e.vx*8*dt,120,560);e.y=clamp(e.y+e.vy*8*dt,220,620);}}
  function updateEnemy(e,dt){if(e.type==='emberback'){updateEmberback(e,dt);return;}if(e.dead)return;e.attackCd=Math.max(0,e.attackCd-dt);const d=dist(player,e);if(d<230){const dx=player.x-e.x,dy=player.y-e.y,dd=Math.max(1,Math.hypot(dx,dy));e.x+=dx/dd*72*dt;e.y+=dy/dd*72*dt;if(dd<28&&e.attackCd<=0){e.attackCd=1.1;let dmg=10;if(player.guarded){dmg=1;player.guarded=false;e.hp-=6+player.skills.guard.level*2;toast('Brace held — countered');if(e.hp<=0)defeatEnemy(e);}player.hp=Math.max(0,player.hp-dmg);if(player.hp<=0){player.hp=player.maxHp;player.energy=50;player.x=900;player.y=600;player.coins=Math.max(0,player.coins-10);log('You were carried back to Briar Glen. The wilds collected their price.','combat');}}}else{e.wander-=dt;if(e.wander<=0){e.vx=rand(-1,1);e.vy=rand(-1,1);e.wander=rand(2,6);}e.x+=e.vx*18*dt;e.y+=e.vy*18*dt;}}

  function respawn(dt){for(const r of world.resources){if(r.available)continue;r.respawn-=dt;if(r.respawn<=0){r.available=true;r.quality=clamp(r.quality+rand(-.25,.25),.7,2.8);}}if(world.enemies.filter(e=>!e.dead).length<7&&Math.random()<dt*.03)spawnWolf(rand(1220,1690),rand(270,680));}
  function updateWeather(dt){world.weatherTimer-=dt;if(world.weatherTimer<=0){const old=world.weather;world.weather=Math.random()<.38?'rain':'clear';world.weatherTimer=rand(160,300);if(old!==world.weather)log(world.weather==='rain'?'Rain settles over Briar Glen. Herbs will come up richer.':'The rain clears. Roads dry and travel quickens.','world');}}
  function updateClock(dt){world.minute+=dt*5.2;if(world.minute>=1440){world.minute-=1440;world.day++;log(`Day ${world.day} begins. Prices and shortages have shifted.`,'world');for(const n of npcs)n.trust=clamp(n.trust-.03,0,10);}world.minute=Math.max(0,world.minute);}

  function apprenticeState(){if(!player.apprentice||typeof player.apprentice!=='object'||!player.apprentice.values)player.apprentice=normalizeApprentice(player.apprentice);return player.apprentice;}
  function apprenticeRemember(text){const a=apprenticeState();a.memory.push({day:world.day,minute:world.minute,text});if(a.memory.length>10)a.memory.shift();}
  function apprenticeMetric(){const trust=npcs.reduce((s,n)=>s+n.trust,0),skill=Object.values(player.skills).reduce((s,x)=>s+x.level+x.xp/100,0),pack=Object.entries(player.inventory).reduce((s,[id,slot])=>s+(itemDefs[id]?.base||0)*slot.qty*.025,0);return player.coins*.04+player.hp*.025+trust*1.6+(player.servicesCompleted||0)*1.5+skill*.25+pack;}
  function apprenticeValue(kind){return Number(apprenticeState().values?.[kind]?.value||0);}
  function deriveApprenticeIdentity(a=apprenticeState()){const entries=Object.entries(apprenticeSpecialties).map(([key,def])=>({key,label:def.label,score:Math.max(0,Number(a.specialties?.[key]||0))})).sort((x,y)=>y.score-x.score),top=entries[0],second=entries[1],total=entries.reduce((s,x)=>s+x.score,0);let next={key:null,label:'Unformed',confidence:0,score:top?.score||0,sinceDecision:a.identity?.sinceDecision||0};if((top?.score||0)>=2.25){if((top.score-(second?.score||0))<.65&&total>=5)next={key:'generalist',label:'Generalist',confidence:clamp(top.score/Math.max(1,total),0,1),score:top.score,sinceDecision:a.identity?.label==='Generalist'?a.identity.sinceDecision:a.decisions};else next={key:top.key,label:top.label,confidence:clamp(top.score/Math.max(1,total),0,1),score:top.score,sinceDecision:a.identity?.key===top.key?a.identity.sinceDecision:a.decisions};}const changed=a.identity?.label!==next.label;a.identity=next;if(changed&&next.label!=='Unformed')apprenticeRemember(`Identity emerging: ${next.label} from repeated experience.`);return a.identity;}
  function updateApprenticeSpecialties(plan,success,reward){const a=apprenticeState(),delta=success?(0.75+Math.max(0,reward)*.18):-0.18;for(const [key,def] of Object.entries(apprenticeSpecialties)){const affinity=Number(def.affinity?.[plan.kind]||0);if(!affinity)continue;a.specialties[key]=Math.max(0,Number(a.specialties[key]||0)+delta*affinity);}return deriveApprenticeIdentity(a);}
  function apprenticeSpecialtyBias(kind){const a=apprenticeState(),entries=Object.entries(apprenticeSpecialties),total=entries.reduce((s,[key])=>s+Math.max(0,Number(a.specialties?.[key]||0)),0);if(total<2)return 0;const weighted=entries.reduce((s,[key,def])=>s+Math.max(0,Number(a.specialties?.[key]||0))*Number(def.affinity?.[kind]||0),0)/total;return clamp(weighted*Math.min(2.4,total*.16),0,2.4);}
  function apprenticeContextRecord(key){const a=apprenticeState();return a.contexts[key]||(a.contexts[key]={tries:0,value:0,failStreak:0});}
  function apprenticeContextValue(key){return Number(apprenticeState().contexts?.[key]?.value||0);}
  function apprenticePlanSignature(candidate){return [candidate.kind,candidate.npcId||'',candidate.itemId||'',candidate.supplierId||'',candidate.enemyId||''].join(':');}
  function apprenticeContextKey(kind,data={}){if(data.contextKey)return data.contextKey;if(data.npcId&&data.itemId)return `${kind}:npc:${data.npcId}:${data.itemId}`;const need=dominantTownNeed();return `${kind}:town:${need.key}`;}
  function apprenticeObjectiveMeta(kind,data={}){if(data.objectiveId)return{id:data.objectiveId,label:data.objectiveLabel||data.objectiveId};if(kind==='service'&&data.npcId&&data.itemId){const n=npcs.find(x=>x.id===data.npcId);return{id:`service:${data.npcId}:${data.itemId}`,label:`Restore ${n?.name||data.npcId}'s ${itemDefs[data.itemId]?.name||data.itemId}`};}if(data.npcId&&data.itemId){const n=npcs.find(x=>x.id===data.npcId);return{id:`request:${data.npcId}:${data.itemId}`,label:`Resolve ${n?.name||data.npcId}'s need for ${itemDefs[data.itemId]?.name||data.itemId}`};}if(kind==='combat'&&data.requestNpcId){const n=npcs.find(x=>x.id===data.requestNpcId);return{id:`request:${data.requestNpcId}:hide`,label:`Secure Wolf Hide for ${n?.name||data.requestNpcId}`};}const need=dominantTownNeed();if(['gather','craft','connect'].includes(kind)&&need.value>2)return{id:`stabilize:${need.key}`,label:`Stabilize Briar Glen's ${need.label} supply`};return null;}
  function apprenticeObjectiveSatisfied(objective){if(!objective?.id)return true;const parts=objective.id.split(':');if(parts[0]==='request'){const n=npcs.find(x=>x.id===parts[1]);return !n||npcNeedScore(n,parts[2])<1.1;}if(parts[0]==='client'){const n=npcs.find(x=>x.id===parts[1]);return !n||n.providerCall?.itemId!==parts[2]||n.seekingProviderFor!==parts[2];}if(parts[0]==='service'){const n=npcs.find(x=>x.id===parts[1]),service=n&&damagedArtifactForNpc(n);return !n||!service||service.id!==parts[2]||service.ratio>.35;}if(parts[0]==='danger')return !liveEnemy(parts[1]);if(parts[0]==='stabilize'){const need=dominantTownNeed();return need.key!==parts[1]||need.value<2;}return false;}
  function closeApprenticeObjective(status){const a=apprenticeState();if(!a.objective)return;a.objectiveHistory.push({day:world.day,id:a.objective.id,label:a.objective.label,status});if(a.objectiveHistory.length>8)a.objectiveHistory.shift();apprenticeRemember(`${status==='completed'?'◆':'◇'} Objective ${status}: ${a.objective.label}`);a.objective=null;}
