  function updatePlayer(dt){let dx=0,dy=0;if(keys.has('KeyW')||keys.has('ArrowUp'))dy--;if(keys.has('KeyS')||keys.has('ArrowDown'))dy++;if(keys.has('KeyA')||keys.has('ArrowLeft'))dx--;if(keys.has('KeyD')||keys.has('ArrowRight'))dx++;let speed=player.speed*(world.weather==='rain'?.93:1);if(inventoryWeight()>18)speed*=.78;if(dx||dy){clearNavigation();const len=Math.hypot(dx,dy);player.x=clamp(player.x+dx/len*speed*dt,18,world.w-18);player.y=clamp(player.y+dy/len*speed*dt,18,world.h-18);player.energy=Math.max(0,player.energy-dt*.7);}else if(navigation.active){const entity=navigationEntity(navigation.target);if(navigation.target&&!entity){clearNavigation();}else{if(entity){navigation.x=entity.x;navigation.y=entity.y;}const dd=Math.hypot(navigation.x-player.x,navigation.y-player.y),stop=navigationStop(navigation.target);if(dd<=stop){const target=navigation.target;clearNavigation();if(target)interactNavigationTarget(target);}else{player.x=clamp(player.x+(navigation.x-player.x)/dd*speed*dt,18,world.w-18);player.y=clamp(player.y+(navigation.y-player.y)/dd*speed*dt,18,world.h-18);player.energy=Math.max(0,player.energy-dt*.7);}}}else player.energy=Math.min(player.maxEnergy,player.energy+dt*2.2);player.attackCd=Math.max(0,player.attackCd-dt);player.attackArc=Math.max(0,player.attackArc-dt);}

  function update(dt){updateApprentice(dt);updatePlayer(dt);updateClock(dt);updateWeather(dt);for(const n of npcs)updateNPC(n,dt);for(const e of world.enemies)updateEnemy(e,dt);respawn(dt);deriveIdentity();}

  function worldToScreen(x,y){return{x:x-camera.x,y:y-camera.y};}
  function drawGround(){ctx.fillStyle=world.weather==='rain'?'#27332d':'#2d3a2c';ctx.fillRect(0,0,canvas.width,canvas.height);for(const z of zones){const p=worldToScreen(z.x,z.y);ctx.fillStyle=z.color;ctx.globalAlpha=.58;ctx.fillRect(p.x,p.y,z.w,z.h);ctx.globalAlpha=1;ctx.fillStyle='rgba(240,239,228,.65)';ctx.font='12px system-ui';ctx.fillText(z.name,p.x+10,p.y+18);}if(world.weather==='rain'){ctx.strokeStyle='rgba(184,208,220,.22)';ctx.lineWidth=1;for(let i=0;i<80;i++){const x=(i*83+performance.now()*.12)%canvas.width,y=(i*47+performance.now()*.22)%canvas.height;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-4,y+10);ctx.stroke();}}}
